svg.script:
//!export-start
let _pn_value = 50;
let _pn_min = 0;
let _pn_max = 100;
let _pn_step = 1;
let _pn_stepClick = 10;
let _ps_variant = 'normal';
let _pb_disabled = false;
//!export-end

var __busyUntil = 0;

function toBool(v) {
    if (v === true || v === 1) return true;
    var s = String(v).toLowerCase();
    return s === 'true' || s === '1' || s === 'on';
}

function toNum(v) {
    if (v === true || v === 'true') return 1;
    if (v === false || v === 'false') return 0;
    var n = parseFloat(v);
    return isNaN(n) ? 0 : n;
}

function apply() {
    var preview = document.getElementById('ob_preview');
    if (preview && preview.parentNode) { preview.parentNode.removeChild(preview); }
    var el = document.getElementById('ob_el');
    if (!el) return;
    el.value = toNum(_pn_value);
    el.min = toNum(_pn_min);
    el.max = toNum(_pn_max);
    el.step = toNum(_pn_step);
    el.stepClick = toNum(_pn_stepClick);
    el.variant = String(_ps_variant);
    el.disabled = toBool(_pb_disabled);
}

function putValue(id, value) {
    if (Date.now() < __busyUntil && ["_pn_value"].indexOf(id) >= 0) return;
    if (id === '_pn_value') { _pn_value = toNum(value); }
    if (id === '_pn_min') { _pn_min = toNum(value); }
    if (id === '_pn_max') { _pn_max = toNum(value); }
    if (id === '_pn_step') { _pn_step = toNum(value); }
    if (id === '_pn_stepClick') { _pn_stepClick = toNum(value); }
    if (id === '_ps_variant') { _ps_variant = String(value); }
    if (id === '_pb_disabled') { _pb_disabled = toBool(value); }
    apply();
}

function postValue(id, value) {
    // replaced at runtime: writes value to the tag bound to "id"
}

(function () {
    var el = document.getElementById('ob_el');
    if (!el) return;
    var timer = null;
    el.addEventListener('value', function (ev) {
        if (!(true)) return;
        _pn_value = toNum(ev.detail);
        __busyUntil = Date.now() + 1250;
        if (timer) { clearTimeout(timer); }
        timer = setTimeout(function () { timer = null; postValue('_pn_value', _pn_value); }, 250);
    });
})();

function fitBox() {
    var root = document.getElementById('ob_root');
    var fo = document.getElementById('ob_fo');
    var el = document.getElementById('ob_el');
    if (!root || !fo || !el) return;
    var w = parseFloat(root.getAttribute('width')) || 288;
    var h = parseFloat(root.getAttribute('height')) || 48;
    if (root.getAttribute('viewBox') !== '0 0 ' + w + ' ' + h) {
        root.setAttribute('viewBox', '0 0 ' + w + ' ' + h);
    }
    fo.setAttribute('width', w);
    fo.setAttribute('height', h);

}

(function () {
    var root = document.getElementById('ob_root');
    fitBox();
    if (root && window.MutationObserver) {
        new MutationObserver(fitBox).observe(root, { attributes: true, attributeFilter: ['width', 'height'] });
    }
})();

apply();
